'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const I=require('./index.cjs'),S=require('./schema.cjs'),B=require('./backend.cjs'),F=require('../keydb-qualification-unused-jit-cleanup-receipts/fixtures.cjs'),X=require('../keydb-qualification-unused-jit-cleanup-receipts/fence-fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT,python=process.env.PUBLIC_TEST_PYTHON,source=process.env.PUBLIC_TEST_SOURCE;assert(root&&python&&source);
function session(){const s=new S.PhaseSession();for(const r of X.records().slice(0,3)){const v=s.reserve(r);s.accept(v);}return s;}
function request(){const rows=X.records(),j=rows[2];return {schema:S.RUNTIME,operation_id:rows[3].operation_id,binding:j.binding,producer_profile:S.PROFILE,returned_runner_id:j.details.runner_id,jit_ack_record_sha256:S.hash(j),state:'MAY_CREATE'};}
test('parent poisons fence capability before acknowledging runtime even with zero lease frames',()=>{const s=session(),r=request(),ack=s.reserveRuntime(r);assert(s.mayCreate);assert.equal(s.createFrames,0);assert.equal(ack.scope,'CURRENT_PARENT_SESSION_ONLY');assert.equal(ack.request_sha256,S.hash(r));assert(!Object.hasOwn(ack,'artifact_id'));assert.throws(()=>s.reserve(X.records()[3]));assert.throws(()=>s.terminal(66,null));assert.throws(()=>s.reserveRuntime(r));});
test('runtime reservation requires exact already acknowledged JIT ID and binding',()=>{for(const key of ['returned_runner_id','jit_ack_record_sha256']){const s=session(),r=request();r[key]=key==='returned_runner_id'?992:'f'.repeat(64);assert.throws(()=>s.reserveRuntime(r));}assert.throws(()=>new S.PhaseSession().reserveRuntime(request()));});
test('ordinary lease frame cannot reserve create before the parent runtime handover',()=>{const s=session();assert.throws(()=>s.reserve(F.producerRecords(false)[3]));});
async function actualPipe(fault){const dir=fs.mkdtempSync(path.join(root,'runtime-ack-')),f=F.fixture(dir,{mode:'normal',reconcile:false}),b=F.binding();f.items.clear();f.raws.clear();const job=f.jobMap.get(777);job.status='in_progress';job.conclusion=null;job.steps[0].status='in_progress';job.steps[0].conclusion=null;job.steps[0].completed_at=null;const marker=path.join(dir,'PUBLIC_RUNTIME_ENTERED');
 const env={...F.env(f.c),GITHUB_JOB:'keydb_qualification_v1',RUNNER_NAME:job.runner_name,RUNNER_TEMP:dir,RUNNER_PRIVATE_PROFILE:'blazing-keydb-parity-qualification-v1','INPUT_SDK-SHA':b.sdk_sha,'INPUT_PRODUCER-JOB-ID':'777',PUBLIC_BINDING:S.canonical(b),PUBLIC_RUNTIME_MARKER:marker};for(const k of ['PATH','HOME','TMPDIR'])if(process.env[k])env[k]=process.env[k];const frames=[];let controlACKs=0;
 const worker=async raw=>{const r=JSON.parse(raw);frames.push(r);return B.persistReceipt(r,B.environmentContext(env,b.sdk_sha,'777'),{...f.deps,directory:fs.mkdtempSync(path.join(dir,'phase-'))});};
 const spawnChild=(exe,args,options)=>{assert.deepEqual(args.slice(0,3),['-I','-S','-c']);const fixture=path.join(__dirname,'tests/runtime_child.py');const child=spawn(exe,['-I','-c',`import sys,runpy;sys.path.insert(0,${JSON.stringify(source)});runpy.run_path(${JSON.stringify(fixture)},run_name='__main__')`],options);const write=child.stdio[4].write.bind(child.stdio[4]);child.stdio[4].write=(raw)=>{const ack=JSON.parse(raw);if(ack.schema===S.RUNTIME_ACK){controlACKs++;if(fault==='missing'){child.stdio[4].end();return true;}if(fault==='partial'){write(raw.slice(0,20));child.stdio[4].end();return true;}if(fault==='wrong-hash')ack.request_sha256='f'.repeat(64);if(fault==='durable-spoof'){ack.schema='just-akash/keydb-qualification-durable-ack/v1';ack.artifact_id=1;}return write(S.canonical(ack)+'\n');}return write(raw);};return child;};
 let result=null;try{result=await I.supervise({python,env,worker,spawnChild});}catch{}const out={fault,runtime_entered:fs.existsSync(marker),controlACKs,durable_phases:frames.map(r=>r.phase),parent_complete:!!result,NO_CREATE:!!result?.terminal_no_create};fs.writeFileSync(path.join(dir,'observation-safe.json'),JSON.stringify(out)+'\n');return out;}
test('actual FD handshake allows runtime only after live parent ACK, without a fake durable phase',async()=>{const x=await actualPipe('none');assert(x.runtime_entered&&x.parent_complete);assert.equal(x.controlACKs,1);assert.deepEqual(x.durable_phases,['NO_WIRE','UNKNOWN','ACK']);assert(!x.NO_CREATE);});
for(const fault of ['missing','partial','wrong-hash','durable-spoof'])test('actual '+fault+' parent ACK prevents runtime unlock and positive fence',async()=>{const x=await actualPipe(fault);assert.equal(x.controlACKs,1);assert(!x.runtime_entered&&!x.parent_complete&&!x.NO_CREATE);assert.deepEqual(x.durable_phases,['NO_WIRE','UNKNOWN','ACK']);});
